-- Kurs Młynarz: odtwarzalny patch wyłącznie treści i opisu, bez zmiany kont, postępu, płatności, RLS i publikacji.
BEGIN;
on conflict(course_slug,lesson_no) do update set title_pl=excluded.title_pl,material=public.ta_lessons.material||excluded.material,updated_at=now();
update public.ta_courses set description_pl='12 lekcji tradycyjnego młynarstwa: budowa ziarna, przygotowanie i czyszczenie surowca, para kamieni młyńskich, koło wodne i przekładnie, rowki furrows, wyciąg mąki, odsiewanie, popiół, zagrożenie pyłem, magazynowanie, kontrola parametrów mąki, diagnostyka, bilans masowy oraz projekt końcowy. Kurs edukacyjny, nie zastępuje szkolenia stanowiskowego ani uprawnień do obsługi czynnego młyna.' where slug='mlynarz-tradycyjny';
update public.ta_course_previews set curiosity='Dlaczego obraca się górny kamień młyński, czym jest wyciąg mąki i dlaczego pył mączny potrafi eksplodować?',scenario='Do młyna trafia 500 kg ziarna. Czyścisz partię, projektujesz drogę przemiału, obliczasz bilans i zapisujesz kontrole bezpieczeństwa.',outcome_1='Rozpoznasz budowę ziarna, hopper, shoe, runner, bedstone, rowki i napęd młyna.',outcome_2='Obliczysz przełożenie zębate, wyciąg mąki, popiół i wydajność oraz odróżnisz wskaźniki jakości.',outcome_3='Opracujesz dokumentację magazynowania, kontroli zanieczyszczeń, SJA i projekt produkcji z bilansem masowym.',source_url='https://www.museum.com/audioguide/431/6/EN',module_titles='["I. Ziarno, czyszczenie i budowa młyna (1–4)","II. Kamienie, przemiał, mąka i BHP (5–8)","III. Magazynowanie, kontrola jakości i projekt (9–12)"]'::jsonb,review_status='review_needed',editorial_note='12 opracowanych lekcji, źródła muzealne, branżowe i HSE, zadania oraz obliczenia. Wymaga recenzji młynarza, analizy bezpieczeństwa lokalnego, testu zalogowanego ucznia, egzaminu i potwierdzenia publikacji SVG w Expo.',updated_at=now() where course_slug='mlynarz-tradycyjny';
COMMIT;
