insert into public.ta_lessons(course_slug,lesson_no,title_pl,material) values
('mlynarz-tradycyjny',0,'1. Ziarno: bielmo, okrywa i zarodek','{"module":1,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Ziarno pszenicy zawiera skrobiowe bielmo, zewnętrzne okrywy oraz zarodek. Ich proporcje mają znaczenie dla składu mąki. Młynarz ocenia również wilgotność, gatunek i zanieczyszczenia, nie tylko kolor."},{"heading":"Przykład","text":"W 100 kg partii znajduje się 5 kg domieszek. Po ich usunięciu pozostaje 95 kg surowca, a nie 95 kg mąki."},{"heading":"Ćwiczenie","text":"Narysuj przekrój ziarna, podpisz trzy części i sporządź kartę przyjęcia partii."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. W 100 kg partii znajduje się 5 kg domieszek. Po ich usunięciu pozostaje 95 kg surowca, a nie 95 kg mąki."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Ziarno pszenicy zawiera skrobiowe bielmo, zewnętrzne okrywy oraz zarodek. Ich proporcje mają znaczenie dla składu mąki. Młynarz ocenia również wilgotność, gatunek i zanieczyszczenia, nie tylko kolor."}],"references":[{"label":"Źródło","url":"https://asbe.org/article/extraction-rate/"}],"learning":{"question":"Co jest głównymi częściami ziarna?","options":["Bielmo, okrywy, zarodek.","Bielmo, popiół, gluten jako organy.","Kora, rdzeń i łodyga.","Piasta, okrywa i zarodek."],"correct":0,"example":"Bielmo, okrywy, zarodek.","explanation":"W 100 kg partii znajduje się 5 kg domieszek. Po ich usunięciu pozostaje 95 kg surowca, a nie 95 kg mąki.","task":"Narysuj przekrój ziarna, podpisz trzy części i sporządź kartę przyjęcia partii.","feedback":["Tak. W 100 kg partii znajduje się 5 kg domieszek. Po ich usunięciu pozostaje 95 kg surowca, a nie 95 kg mąki.","Nie. W 100 kg partii znajduje się 5 kg domieszek. Po ich usunięciu pozostaje 95 kg surowca, a nie 95 kg mąki.","Nie. W 100 kg partii znajduje się 5 kg domieszek. Po ich usunięciu pozostaje 95 kg surowca, a nie 95 kg mąki.","Nie. W 100 kg partii znajduje się 5 kg domieszek. Po ich usunięciu pozostaje 95 kg surowca, a nie 95 kg mąki."]},"illustration":"mlynarz-ziarno"}'::jsonb),
('mlynarz-tradycyjny',1,'2. Czyszczenie: sita, magnes i separator kamieni','{"module":1,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Przed przemiałem usuwa się plewy, pył, kamienie i części metalowe. Magnes nie usuwa każdego obcego materiału, dlatego młyny używają kilku metod separacji i kontrolują strumień surowca."},{"heading":"Przykład","text":"Z 500 kg ziarna odrzucono 12 kg zanieczyszczeń. Uzysk czystego surowca to 488/500=97,6%; to nie wyciąg mąki."},{"heading":"Ćwiczenie","text":"Zaprojektuj proces od przyjęcia do młyna, dobierz separację metalu, kamieni, plew i pyłu."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. Z 500 kg ziarna odrzucono 12 kg zanieczyszczeń. Uzysk czystego surowca to 488/500=97,6%; to nie wyciąg mąki."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Przed przemiałem usuwa się plewy, pył, kamienie i części metalowe. Magnes nie usuwa każdego obcego materiału, dlatego młyny używają kilku metod separacji i kontrolują strumień surowca."}],"references":[{"label":"Źródło","url":"https://www.hse.gov.uk/food/safety-hazards/dustexplosion.htm"}],"learning":{"question":"W partii są stalowe śruby. Co zrobić?","options":["Zwiększyć obroty.","Odseparować zanieczyszczenia i ocenić partię.","Zalać wodą, aby zmiękły.","Pominąć, jeśli śruby są małe."],"correct":1,"example":"Odseparować zanieczyszczenia i ocenić partię.","explanation":"Z 500 kg ziarna odrzucono 12 kg zanieczyszczeń. Uzysk czystego surowca to 488/500=97,6%; to nie wyciąg mąki.","task":"Zaprojektuj proces od przyjęcia do młyna, dobierz separację metalu, kamieni, plew i pyłu.","feedback":["Nie. Z 500 kg ziarna odrzucono 12 kg zanieczyszczeń. Uzysk czystego surowca to 488/500=97,6%; to nie wyciąg mąki.","Tak. Z 500 kg ziarna odrzucono 12 kg zanieczyszczeń. Uzysk czystego surowca to 488/500=97,6%; to nie wyciąg mąki.","Nie. Z 500 kg ziarna odrzucono 12 kg zanieczyszczeń. Uzysk czystego surowca to 488/500=97,6%; to nie wyciąg mąki.","Nie. Z 500 kg ziarna odrzucono 12 kg zanieczyszczeń. Uzysk czystego surowca to 488/500=97,6%; to nie wyciąg mąki."]},"illustration":"craft-mlynarz-tradycyjny"}'::jsonb),
('mlynarz-tradycyjny',2,'3. Kamienie młyńskie: bedstone, runner i podajnik','{"module":1,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Dolny kamień (bedstone) jest nieruchomy, górny (runner) obraca się. Ziarno przechodzi z hopper do shoe, przez otwór i szczelinę między kamieniami. Damsel może rytmicznie poruszać podajnikiem; rowki furrows wspierają transport przemiału."},{"heading":"Przykład","text":"Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia."},{"heading":"Ćwiczenie","text":"Narysuj przekrój młyna od kosza do worka i podpisz wszystkie sześć części."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Dolny kamień (bedstone) jest nieruchomy, górny (runner) obraca się. Ziarno przechodzi z hopper do shoe, przez otwór i szczelinę między kamieniami. Damsel może rytmicznie poruszać podajnikiem; rowki furrows wspierają transport przemiału."}],"references":[{"label":"Źródło","url":"https://www.museum.com/audioguide/431/6/EN"}],"learning":{"question":"Który kamień zwykle jest nieruchomy?","options":["Runner.","Damsel.","Bedstone.","Hopper."],"correct":2,"example":"Bedstone.","explanation":"Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia.","task":"Narysuj przekrój młyna od kosza do worka i podpisz wszystkie sześć części.","feedback":["Nie. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia.","Nie. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia.","Tak. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia.","Nie. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia."]},"illustration":"mlynarz-kamienie"}'::jsonb),
('mlynarz-tradycyjny',3,'4. Przekładnie i obroty młyna wodnego','{"module":1,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Koło wodne przekazuje energię przez wały i koła zębate. Gdy większe koło napędza mniejsze, obroty wyjściowe mogą być wyższe przy zmianie momentu; rzeczywiste straty zależą od konstrukcji."},{"heading":"Przykład","text":"Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu."},{"heading":"Ćwiczenie","text":"Narysuj wał i stone nut. Policz także wariant 60 zębów do 20 przy 12 obr./min."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Koło wodne przekazuje energię przez wały i koła zębate. Gdy większe koło napędza mniejsze, obroty wyjściowe mogą być wyższe przy zmianie momentu; rzeczywiste straty zależą od konstrukcji."}],"references":[{"label":"Źródło","url":"https://www.museum.com/audioguide/431/6/EN"}],"learning":{"question":"72 zęby, 12 obr./min, napęd 18 zębów. Ile obrotów ma koło wyjściowe?","options":["3 obr./min.","12 obr./min.","24 obr./min.","48 obr./min."],"correct":3,"example":"48 obr./min.","explanation":"Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu.","task":"Narysuj wał i stone nut. Policz także wariant 60 zębów do 20 przy 12 obr./min.","feedback":["Nie. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu.","Nie. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu.","Nie. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu.","Tak. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu."]},"illustration":"mlynarz-przekladnia"}'::jsonb),
('mlynarz-tradycyjny',4,'5. Rowki furrows i zużycie kamieni','{"module":2,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Powierzchnia kamienia ma rowki furrows i obszary lands. Ich geometria wpływa na mielenie i transport surowca. Zużycie, pęknięcie i przegrzewanie są różnymi problemami wymagającymi odrębnej diagnozy."},{"heading":"Przykład","text":"Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych."},{"heading":"Ćwiczenie","text":"Narysuj przekrój powierzchni i tabelę czterech objawów z hipotezami i kontrolą."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Powierzchnia kamienia ma rowki furrows i obszary lands. Ich geometria wpływa na mielenie i transport surowca. Zużycie, pęknięcie i przegrzewanie są różnymi problemami wymagającymi odrębnej diagnozy."}],"references":[{"label":"Źródło","url":"https://www.museum.com/audioguide/431/6/EN"}],"learning":{"question":"Dlaczego sama średnica kamienia nie wystarcza do oceny jakości?","options":["Liczy się też geometria rowków i stan powierzchni.","Bo rowki nie wpływają na przemiał.","Bo dolny zawsze obraca się szybciej.","Bo ważny jest tylko kolor osłony."],"correct":0,"example":"Liczy się też geometria rowków i stan powierzchni.","explanation":"Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych.","task":"Narysuj przekrój powierzchni i tabelę czterech objawów z hipotezami i kontrolą.","feedback":["Tak. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych.","Nie. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych.","Nie. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych.","Nie. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych."]},"illustration":"mlynarz-kamienie"}'::jsonb),
('mlynarz-tradycyjny',5,'6. Wyciąg mąki i bilans masy','{"module":2,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Wyciąg to procent masy oczyszczonego ziarna przechodzący do określonej frakcji mąki. Wysoki wyciąg może zwiększać udział składników okryw. Nie jest to to samo co popiół czy ilość domieszek."},{"heading":"Przykład","text":"Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200."},{"heading":"Ćwiczenie","text":"Policz wyciąg dla 150/200 i 180/200; opisz różnice składu frakcji."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Wyciąg to procent masy oczyszczonego ziarna przechodzący do określonej frakcji mąki. Wysoki wyciąg może zwiększać udział składników okryw. Nie jest to to samo co popiół czy ilość domieszek."}],"references":[{"label":"Źródło","url":"https://asbe.org/article/extraction-rate/"}],"learning":{"question":"Jaki jest wyciąg 150 kg mąki z 200 kg ziarna?","options":["50%.","75%.","90%.","125%."],"correct":1,"example":"75%.","explanation":"Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200.","task":"Policz wyciąg dla 150/200 i 180/200; opisz różnice składu frakcji.","feedback":["Nie. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200.","Tak. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200.","Nie. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200.","Nie. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200."]},"illustration":"mlynarz-bilans"}'::jsonb),
('mlynarz-tradycyjny',6,'7. Odsiewanie i oznaczanie popiołu','{"module":2,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Sita rozdzielają przemiał według rozmiaru cząstek. Zawartość popiołu jest laboratoryjnym wskaźnikiem mineralnej pozostałości po kontrolowanym spaleniu mąki, a nie bezpośrednią masą otrąb."},{"heading":"Przykład","text":"Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności."},{"heading":"Ćwiczenie","text":"Narysuj rozdział mąki na sita i policz wskaźnik popiołu oraz wyciągu dla innych danych."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Sita rozdzielają przemiał według rozmiaru cząstek. Zawartość popiołu jest laboratoryjnym wskaźnikiem mineralnej pozostałości po kontrolowanym spaleniu mąki, a nie bezpośrednią masą otrąb."}],"references":[{"label":"Źródło","url":"https://asbe.org/article/ash-in-flour/"}],"learning":{"question":"Popiół 0,055 g z próbki 10 g to...","options":["0,055%.","0,11%.","0,55%.","5,5%."],"correct":2,"example":"0,55%.","explanation":"Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności.","task":"Narysuj rozdział mąki na sita i policz wskaźnik popiołu oraz wyciągu dla innych danych.","feedback":["Nie. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności.","Nie. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności.","Tak. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności.","Nie. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności."]},"illustration":"mlynarz-bilans"}'::jsonb),
('mlynarz-tradycyjny',7,'8. Pył mączny, zapłon i bezpieczeństwo młyna','{"module":2,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Podstawy","text":"Pył mączny zawieszony w powietrzu jest palny i może tworzyć atmosferę wybuchową w obecności źródła zapłonu. Zagrożenie obejmuje również sprzęt odpylający, ruchome maszyny i przypadkowe metalowe części w materiale."},{"heading":"Przykład","text":"HSE zaleca ocenę pylenia, odpowiednie odpylanie, usuwanie źródeł zapłonu i kontrolę porządku. Dmuchanie osadów sprężonym powietrzem może wzbić chmurę pyłu."},{"heading":"Ćwiczenie","text":"Przygotuj SJA z 10 zagrożeniami, kontrolą prac elektrycznych i sposobem bezpiecznego usuwania pyłu."},{"heading":"Co sprawdzić","text":"Weryfikuj jednostki, założenia i wynik. HSE zaleca ocenę pylenia, odpowiednie odpylanie, usuwanie źródeł zapłonu i kontrolę porządku. Dmuchanie osadów sprężonym powietrzem może wzbić chmurę pyłu."},{"heading":"Zastosowanie","text":"Wyjaśnij, jak ta wiedza zmienia decyzję w młynie. Pył mączny zawieszony w powietrzu jest palny i może tworzyć atmosferę wybuchową w obecności źródła zapłonu. Zagrożenie obejmuje również sprzęt odpylający, ruchome maszyny i przypadkowe metalowe części w materiale."}],"references":[{"label":"Źródło","url":"https://www.hse.gov.uk/food/safety-hazards/dustexplosion.htm"}],"learning":{"question":"Dlaczego zdmuchiwanie osadzonej mąki może zwiększyć ryzyko?","options":["Bo mąka jest niepalna.","Bo pył zamienia się w metal.","Bo wiatr neutralizuje zapłon.","Bo powstaje potencjalnie zapalna chmura pyłu."],"correct":3,"example":"Bo powstaje potencjalnie zapalna chmura pyłu.","explanation":"HSE zaleca ocenę pylenia, odpowiednie odpylanie, usuwanie źródeł zapłonu i kontrolę porządku. Dmuchanie osadów sprężonym powietrzem może wzbić chmurę pyłu.","task":"Przygotuj SJA z 10 zagrożeniami, kontrolą prac elektrycznych i sposobem bezpiecznego usuwania pyłu.","feedback":["Nie. HSE zaleca ocenę pylenia, odpowiednie odpylanie, usuwanie źródeł zapłonu i kontrolę porządku. Dmuchanie osadów sprężonym powietrzem może wzbić chmurę pyłu.","Nie. HSE zaleca ocenę pylenia, odpowiednie odpylanie, usuwanie źródeł zapłonu i kontrolę porządku. Dmuchanie osadów sprężonym powietrzem może wzbić chmurę pyłu.","Nie. HSE zaleca ocenę pylenia, odpowiednie odpylanie, usuwanie źródeł zapłonu i kontrolę porządku. Dmuchanie osadów sprężonym powietrzem może wzbić chmurę pyłu.","Tak. HSE zaleca ocenę pylenia, odpowiednie odpylanie, usuwanie źródeł zapłonu i kontrolę porządku. Dmuchanie osadów sprężonym powietrzem może wzbić chmurę pyłu."]},"illustration":"diagnosis-mlynarz-tradycyjny"}'::jsonb),
('mlynarz-tradycyjny',8,'9. Magazynowanie ziarna: wilgotność, samonagrzewanie i identyfikowalność','{"module":3,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Wiedza i materiał","text":"Ziarno jest materiałem biologicznym. W nieodpowiednich warunkach wilgoć i temperatura mogą sprzyjać rozwojowi pleśni, szkodników i samonagrzewaniu. Magazynowanie wymaga identyfikacji partii, kontroli warunków, porządku oraz bezpiecznej organizacji przemieszczania surowca. Nie istnieje jedna optymalna wilgotność dla wszystkich zbóż i czasu składowania."},{"heading":"Proces i obliczenie","text":"W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas."},{"heading":"Zadanie zawodowe","text":"Przygotuj kartę magazynową dwóch partii: data, gatunek, masa, wilgotność, temperatura, lokalizacja, obserwacje, wynik kontroli i decyzja. Pokaż, co robisz przy oznakach samonagrzewania bez wchodzenia do wnętrza silosu."},{"heading":"Kryteria kontroli","text":"Oceń jednostki, źródła danych i ryzyko; uzasadnij każdy etap. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas."},{"heading":"Co wynika z przykładu","text":"Nie zamieniaj przykładowych założeń na obowiązujące parametry techniczne. Ziarno jest materiałem biologicznym. W nieodpowiednich warunkach wilgoć i temperatura mogą sprzyjać rozwojowi pleśni, szkodników i samonagrzewaniu. Magazynowanie wymaga identyfikacji partii, kontroli warunków, porządku oraz bezpiecznej organizacji przemieszczania surowca. Nie istnieje jedna optymalna wilgotność dla wszystkich zbóż i czasu składowania."}],"references":[{"label":"Źródło","url":"https://www.hse.gov.uk/food/safety-hazards/dustexplosion.htm"}],"learning":{"question":"Która informacja pomaga ocenić ryzyko przechowywania ziarna?","options":["Wyłącznie kolor worka.","Tylko liczba pracowników zmiany.","Wilgotność, temperatura, gatunek i czas składowania.","Sama cena zakupu ziarna."],"correct":2,"example":"Wilgotność, temperatura, gatunek i czas składowania.","explanation":"W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas.","task":"Przygotuj kartę magazynową dwóch partii: data, gatunek, masa, wilgotność, temperatura, lokalizacja, obserwacje, wynik kontroli i decyzja. Pokaż, co robisz przy oznakach samonagrzewania bez wchodzenia do wnętrza silosu.","feedback":["Nie. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas.","Nie. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas.","Tak. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas.","Nie. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas."]},"illustration":"mlynarz-ziarno"}'::jsonb),
('mlynarz-tradycyjny',9,'10. Kontrola mąki: wilgotność, typ, gluten i zastosowanie','{"module":3,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Wiedza i materiał","text":"Parametry mąki zależą od surowca, przemiału, odsiewania i przechowywania. Zawartość białka, właściwości glutenu w mące pszennej, popiół i wilgotność wpływają na możliwe zastosowania, ale jedna liczba nie przewiduje w pełni jakości wypiekowej. Mąka żytnia lub inne zboża nie powinny być oceniane identyczną procedurą jak pszenna."},{"heading":"Proces i obliczenie","text":"Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej."},{"heading":"Zadanie zawodowe","text":"Zaprojektuj kartę jakości mąki dla piekarni: partia, gatunek, wilgotność, popiół, parametry białka lub glutenu według rodzaju mąki, wynik próby i decyzja. Zaznacz trzy informacje, których nie da się ustalić tylko wzrokiem."},{"heading":"Kryteria kontroli","text":"Oceń jednostki, źródła danych i ryzyko; uzasadnij każdy etap. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej."},{"heading":"Co wynika z przykładu","text":"Nie zamieniaj przykładowych założeń na obowiązujące parametry techniczne. Parametry mąki zależą od surowca, przemiału, odsiewania i przechowywania. Zawartość białka, właściwości glutenu w mące pszennej, popiół i wilgotność wpływają na możliwe zastosowania, ale jedna liczba nie przewiduje w pełni jakości wypiekowej. Mąka żytnia lub inne zboża nie powinny być oceniane identyczną procedurą jak pszenna."}],"references":[{"label":"Źródło","url":"https://asbe.org/article/extraction-rate/"}],"learning":{"question":"Dlaczego nie można określić przydatności każdej mąki wyłącznie po procentowej zawartości białka?","options":["Bo białko nie ma żadnego znaczenia w pieczeniu.","Bo liczą się także właściwości funkcjonalne, gatunek i wymagania produktu.","Bo każde zboże zawiera identyczną jakość glutenu.","Bo kolor opakowania rozstrzyga o wypieku."],"correct":1,"example":"Bo liczą się także właściwości funkcjonalne, gatunek i wymagania produktu.","explanation":"Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej.","task":"Zaprojektuj kartę jakości mąki dla piekarni: partia, gatunek, wilgotność, popiół, parametry białka lub glutenu według rodzaju mąki, wynik próby i decyzja. Zaznacz trzy informacje, których nie da się ustalić tylko wzrokiem.","feedback":["Nie. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej.","Tak. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej.","Nie. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej.","Nie. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej."]},"illustration":"material-mlynarz-tradycyjny"}'::jsonb),
('mlynarz-tradycyjny',10,'11. Usterki młyna: spadek wydajności, przegrzewanie i obce cząstki','{"module":3,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Wiedza i materiał","text":"Przy spadku wydajności młynarz rozróżnia problem dostawy ziarna, podajnika, napędu, kamieni, odsiewacza i magazynu. Zmieniony rozmiar cząstek, nietypowe wibracje lub wysoka temperatura są objawami, nie gotową diagnozą. Ruchomych elementów nie wolno kontrolować ręcznie podczas pracy bez właściwych zabezpieczeń i zatwierdzonej procedury."},{"heading":"Proces i obliczenie","text":"Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo."},{"heading":"Zadanie zawodowe","text":"Zrób drzewo diagnostyczne dla trzech objawów: pylenie, spadek wydajności i podejrzany pył kamienny. W każdej gałęzi uwzględnij bezpieczeństwo, dane kontrolne i możliwość zatrzymania procesu."},{"heading":"Kryteria kontroli","text":"Oceń jednostki, źródła danych i ryzyko; uzasadnij każdy etap. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo."},{"heading":"Co wynika z przykładu","text":"Nie zamieniaj przykładowych założeń na obowiązujące parametry techniczne. Przy spadku wydajności młynarz rozróżnia problem dostawy ziarna, podajnika, napędu, kamieni, odsiewacza i magazynu. Zmieniony rozmiar cząstek, nietypowe wibracje lub wysoka temperatura są objawami, nie gotową diagnozą. Ruchomych elementów nie wolno kontrolować ręcznie podczas pracy bez właściwych zabezpieczeń i zatwierdzonej procedury."}],"references":[{"label":"Źródło","url":"https://www.museum.com/audioguide/431/6/EN"}],"learning":{"question":"Przemiał 200 kg trwał 4 godziny, a następnie 5 godzin. O ile procent zmalała wydajność godzinowa?","options":["10%.","15%.","20%.","25%."],"correct":2,"example":"20%.","explanation":"Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo.","task":"Zrób drzewo diagnostyczne dla trzech objawów: pylenie, spadek wydajności i podejrzany pył kamienny. W każdej gałęzi uwzględnij bezpieczeństwo, dane kontrolne i możliwość zatrzymania procesu.","feedback":["Nie. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo.","Nie. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo.","Tak. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo.","Nie. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo."]},"illustration":"mlynarz-przekladnia"}'::jsonb),
('mlynarz-tradycyjny',11,'12. Projekt końcowy młynarza: partia zboża, przemiał, bilans i BHP','{"module":3,"curriculum_revision":8,"editorial_status":"review_needed","sections":[{"heading":"Wiedza i materiał","text":"Zadanie końcowe łączy przyjęcie partii, czyszczenie, dobór urządzeń, przemiał, odsiewanie, kontrolę mąki i bezpieczeństwo. Uczeń musi umieć wyjaśnić proces od ziarna do oznaczonego worka oraz rozdzielić dane zmierzone, wyliczone i niepotwierdzone. Celem jest projektowa analiza, nie pozwolenie na samodzielną obsługę czynnego młyna."},{"heading":"Proces i obliczenie","text":"Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem)."},{"heading":"Zadanie zawodowe","text":"Przygotuj schemat przepływu, bilans masowy, plan urządzeń, 10-punktową kartę jakości i 10-punktową SJA. Uzasadnij różnicę między wydajnością wsadu a wydajnością mąki i zaznacz ryzyko zapłonu pyłu."},{"heading":"Kryteria kontroli","text":"Oceń jednostki, źródła danych i ryzyko; uzasadnij każdy etap. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem)."},{"heading":"Co wynika z przykładu","text":"Nie zamieniaj przykładowych założeń na obowiązujące parametry techniczne. Zadanie końcowe łączy przyjęcie partii, czyszczenie, dobór urządzeń, przemiał, odsiewanie, kontrolę mąki i bezpieczeństwo. Uczeń musi umieć wyjaśnić proces od ziarna do oznaczonego worka oraz rozdzielić dane zmierzone, wyliczone i niepotwierdzone. Celem jest projektowa analiza, nie pozwolenie na samodzielną obsługę czynnego młyna."}],"references":[{"label":"Źródło","url":"https://asbe.org/article/extraction-rate/"}],"learning":{"question":"Z 490 kg oczyszczonego ziarna otrzymano 367,5 kg mąki. Jaki jest wyciąg?","options":["65%.","70%.","75%.","85%."],"correct":2,"example":"75%.","explanation":"Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem).","task":"Przygotuj schemat przepływu, bilans masowy, plan urządzeń, 10-punktową kartę jakości i 10-punktową SJA. Uzasadnij różnicę między wydajnością wsadu a wydajnością mąki i zaznacz ryzyko zapłonu pyłu.","feedback":["Nie. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem).","Nie. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem).","Tak. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem).","Nie. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem)."]},"illustration":"mlynarz-bilans"}'::jsonb)
